-- Generated by node scripts/prepare-supabase.mjs.
-- Initial Claro setup only: apply ONCE to a project where these migrations are not yet deployed.
-- All migrations run in one transaction. No credentials are included.
begin;

-- 202611180001_setting_priorities.sql
-- Integration contracts only. The task/option teams own all creation and generation flows.
-- Text IDs preserve Claro's existing local task IDs and also accept UUID strings.
create table if not exists public.tasks (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null
);
create table if not exists public.options (
  id text primary key default gen_random_uuid()::text,
  task_id text not null references public.tasks(id) on delete cascade,
  name text not null,
  ratings jsonb not null default '{}'::jsonb check (jsonb_typeof(ratings) = 'object')
);
create index if not exists claro_tasks_user_idx on public.tasks(user_id);
create index if not exists claro_options_task_idx on public.options(task_id);

create table public.universal_priorities (
  user_id uuid not null references auth.users(id) on delete cascade,
  factor text not null check (length(factor) between 1 and 80 and factor = btrim(factor)),
  weight integer not null check (weight between 0 and 100),
  sort_order integer not null check (sort_order >= 0),
  name text not null check (length(btrim(name)) between 1 and 40),
  description text not null default '' check (length(description) <= 140),
  color text not null check (color ~ '^#[0-9a-fA-F]{6}$'),
  primary key (user_id, factor),
  unique (user_id, sort_order)
);
create table public.task_priorities (
  task_id text not null references public.tasks(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  factor text not null check (length(factor) between 1 and 80 and factor = btrim(factor)),
  weight integer not null check (weight between 0 and 100),
  sort_order integer not null check (sort_order >= 0),
  name text not null check (length(btrim(name)) between 1 and 40),
  description text not null default '' check (length(description) <= 140),
  color text not null check (color ~ '^#[0-9a-fA-F]{6}$'),
  -- A removal must not silently reappear through universal fallback.
  excluded boolean not null default false check (not excluded or weight = 0),
  primary key (task_id, user_id, factor)
);
create index claro_task_priorities_user_idx on public.task_priorities(user_id);

alter table public.tasks enable row level security;
alter table public.options enable row level security;
alter table public.universal_priorities enable row level security;
alter table public.task_priorities enable row level security;

create policy claro_tasks_owner on public.tasks for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
-- Restrictive guards also protect against unrelated permissive policies if contracts exist.
create policy claro_tasks_guard on public.tasks as restrictive for all to public
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy claro_options_owner on public.options for all to authenticated
  using (exists (select 1 from public.tasks t where t.id = task_id and t.user_id = (select auth.uid())))
  with check (exists (select 1 from public.tasks t where t.id = task_id and t.user_id = (select auth.uid())));
create policy claro_options_guard on public.options as restrictive for all to public
  using (exists (select 1 from public.tasks t where t.id = task_id and t.user_id = (select auth.uid())))
  with check (exists (select 1 from public.tasks t where t.id = task_id and t.user_id = (select auth.uid())));
create policy claro_universal_owner on public.universal_priorities for select to authenticated
  using (user_id = (select auth.uid()));
create policy claro_task_priorities_owner on public.task_priorities for select to authenticated
  using (user_id = (select auth.uid()) and exists (
    select 1 from public.tasks t where t.id = task_id and t.user_id = (select auth.uid())
  ));

-- Complete sets are replaced atomically through this RPC, never delete-then-insert over HTTP.
-- SECURITY DEFINER is limited to the current authenticated account and owned task.
create function public.save_priorities(p_factors jsonb, p_task_id text default null, p_expected_user_id uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := auth.uid();
  active_count integer;
begin
  if actor is null then raise exception 'Sign in to save priorities.' using errcode = '42501'; end if;
  if p_expected_user_id is not null and p_expected_user_id <> actor then
    raise exception 'Your account changed. Reopen the screen before saving.' using errcode = '42501';
  end if;
  -- Serialize saves/reverts for the account, including the first save (no rows yet).
  perform 1 from auth.users where id = actor for update;
  if p_task_id is not null and not exists (
    select 1 from public.tasks where id = p_task_id and user_id = actor
  ) then raise exception 'Task not found in your account.' using errcode = '42501'; end if;
  if p_factors is null or jsonb_typeof(p_factors) <> 'array' then
    raise exception 'Expected a priority array.';
  end if;
  -- Empty task overrides mean follow universal. Universal can never be empty.
  if p_task_id is not null and jsonb_array_length(p_factors) = 0 then
    delete from public.task_priorities where task_id = p_task_id and user_id = actor;
    return;
  end if;
  select count(*) into active_count from jsonb_array_elements(p_factors) f
    where not coalesce((f->>'excluded')::boolean, false);
  if active_count < 2 or active_count > 8 or
    (select sum((f->>'weight')::numeric) from jsonb_array_elements(p_factors) f) is distinct from 100::numeric or
    exists (select 1 from jsonb_array_elements(p_factors) f where
      jsonb_typeof(f->'weight') is distinct from 'number' or
      (f->>'weight')::numeric <> trunc((f->>'weight')::numeric) or
      (f->>'weight')::numeric not between 0 and 100 or
      (coalesce((f->>'excluded')::boolean, false) and ((f->>'weight')::numeric <> 0 or p_task_id is null))) or
    (select count(distinct f->>'factor') from jsonb_array_elements(p_factors) f) <> jsonb_array_length(p_factors) or
    (select count(distinct lower(btrim(f->>'name'))) from jsonb_array_elements(p_factors) f
      where not coalesce((f->>'excluded')::boolean, false)) <> active_count then
    raise exception 'Use 2–8 unique factors with exactly 100 whole points.';
  end if;
  if p_task_id is null then
    delete from public.universal_priorities where user_id = actor;
    insert into public.universal_priorities(user_id, factor, weight, sort_order, name, description, color)
      select actor, f->>'factor', (f->>'weight')::integer, ordinality::integer - 1,
        btrim(f->>'name'), coalesce(f->>'description', ''), f->>'color'
      from jsonb_array_elements(p_factors) with ordinality as rows(f, ordinality);
  else
    delete from public.task_priorities where task_id = p_task_id and user_id = actor;
    insert into public.task_priorities(task_id, user_id, factor, weight, sort_order, name, description, color, excluded)
      select p_task_id, actor, f->>'factor', (f->>'weight')::integer, ordinality::integer - 1,
        btrim(f->>'name'), coalesce(f->>'description', ''), f->>'color', coalesce((f->>'excluded')::boolean, false)
      from jsonb_array_elements(p_factors) with ordinality as rows(f, ordinality);
  end if;
end;
$$;
revoke all on function public.save_priorities(jsonb, text, uuid) from public, anon;
grant execute on function public.save_priorities(jsonb, text, uuid) to authenticated;
revoke all on public.universal_priorities, public.task_priorities from anon, authenticated;
grant select on public.universal_priorities, public.task_priorities to authenticated;
-- The task/option teams can populate their own contracts; this feature only reads them.
grant select, insert, update, delete on public.tasks, public.options to authenticated;

create function public.seed_claro_priorities() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.universal_priorities(user_id, factor, weight, sort_order, name, description, color) values
    (new.id, 'cost', 30, 0, 'Cost', 'Total cost and long-term value', '#A8B79B'),
    (new.id, 'quality', 30, 1, 'Quality', 'Product or service performance', '#CBD8B4'),
    (new.id, 'delivery', 10, 2, 'Delivery', 'Speed and consistency of delivery', '#EEC4A2'),
    (new.id, 'reliability', 20, 3, 'Reliability', 'Dependability and risk of disruption', '#D3C4DF'),
    (new.id, 'sustainability', 10, 4, 'Sustainability', 'Environmental and ethical impact', '#B6D6D1');
  return new;
end;
$$;
revoke all on function public.seed_claro_priorities() from public, anon, authenticated;
create trigger claro_seed_priorities after insert on auth.users
  for each row execute function public.seed_claro_priorities();

-- Existing accounts receive defaults only if they have no priorities.
insert into public.universal_priorities(user_id, factor, weight, sort_order, name, description, color)
select u.id, d.* from auth.users u cross join (values
  ('cost', 30, 0, 'Cost', 'Total cost and long-term value', '#A8B79B'),
  ('quality', 30, 1, 'Quality', 'Product or service performance', '#CBD8B4'),
  ('delivery', 10, 2, 'Delivery', 'Speed and consistency of delivery', '#EEC4A2'),
  ('reliability', 20, 3, 'Reliability', 'Dependability and risk of disruption', '#D3C4DF'),
  ('sustainability', 10, 4, 'Sustainability', 'Environmental and ethical impact', '#B6D6D1')
) d(factor, weight, sort_order, name, description, color)
where not exists (select 1 from public.universal_priorities p where p.user_id = u.id);

-- 202611180002_account_data.sql
alter table public.tasks
  add column notes text not null default '',
  add column due_date date,
  add column done boolean not null default false;
alter table public.tasks add constraint claro_task_title check (length(btrim(title)) between 1 and 120);
alter table public.tasks add constraint claro_task_notes check (length(notes) <= 2000);

-- Immutable snapshots preserve the priorities used when the decision was made.
create function public.claro_valid_snapshot(value jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$
declare item jsonb; total numeric := 0; keys text[] := '{}';
begin
  if value is null or jsonb_typeof(value) <> 'array' then return false; end if;
  if jsonb_array_length(value) < 1 or jsonb_array_length(value) > 32 then return false; end if;
  for item in select * from jsonb_array_elements(value) loop
    if jsonb_typeof(item) <> 'object' or
      jsonb_typeof(item->'id') is distinct from 'string' or length(btrim(item->>'id')) = 0 or
      item->>'id' = any(keys) or
      jsonb_typeof(item->'name') is distinct from 'string' or length(btrim(item->>'name')) = 0 or
      jsonb_typeof(item->'description') is distinct from 'string' or
      jsonb_typeof(item->'color') is distinct from 'string' or (item->>'color') !~ '^#[0-9a-fA-F]{6}$' or
      jsonb_typeof(item->'weight') is distinct from 'number' then return false; end if;
    if (item->>'weight')::numeric not between 0 and 100 or
      (item->>'weight')::numeric <> trunc((item->>'weight')::numeric) then return false; end if;
    total := total + (item->>'weight')::numeric;
    keys := array_append(keys, item->>'id');
  end loop;
  return total = 100;
end;
$$;

create table public.decisions (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (length(btrim(title)) between 1 and 120),
  category text not null default 'Business',
  choice text not null check (length(btrim(choice)) between 1 and 300),
  notes text not null default '' check (length(notes) <= 3000),
  alternatives text[] not null default '{}',
  review_date date,
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  priorities jsonb not null check (public.claro_valid_snapshot(priorities))
);
create index claro_decisions_user_updated_idx on public.decisions(user_id, updated_at desc);
alter table public.decisions enable row level security;
create policy claro_decisions_owner on public.decisions for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy claro_decisions_guard on public.decisions as restrictive for all to public
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke all on public.decisions from anon;
grant select, insert, update, delete on public.decisions to authenticated;

-- One request commits changed records only; unrelated records are never replaced/deleted.
-- SECURITY INVOKER keeps RLS in force, even for IDs that collide with another account.
create function public.save_app_records(p_tasks jsonb default '[]', p_decisions jsonb default '[]', p_import_only boolean default false, p_expected_user_id uuid default null)
returns void language plpgsql security invoker set search_path = '' as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'Sign in to save your data.' using errcode = '42501'; end if;
  if p_expected_user_id is distinct from actor then raise exception 'Your account changed. Reopen the screen before saving.' using errcode = '42501'; end if;
  if p_tasks is null or p_decisions is null or jsonb_typeof(p_tasks) <> 'array' or jsonb_typeof(p_decisions) <> 'array' then
    raise exception 'Expected arrays of tasks and decisions.';
  end if;
  insert into public.tasks(id, user_id, title, notes, due_date, done)
    select t.id, actor, t.title, coalesce(t.notes, ''), t.due_date, coalesce(t.done, false)
    from jsonb_to_recordset(p_tasks) as t(id text, title text, notes text, due_date date, done boolean)
  on conflict (id) do update set title = excluded.title, notes = excluded.notes,
    due_date = excluded.due_date, done = excluded.done
  where public.tasks.user_id = actor and not p_import_only;
  if (select count(*) from public.tasks where user_id = actor and id in
    (select item->>'id' from jsonb_array_elements(p_tasks) item)) <> jsonb_array_length(p_tasks) then
    raise exception 'A task could not be saved to this account.' using errcode = '42501';
  end if;
  insert into public.decisions(id, user_id, title, category, choice, notes, alternatives, review_date, status, created_at, updated_at, priorities)
    select d.id, actor, d.title, coalesce(d.category, 'Business'), d.choice, coalesce(d.notes, ''),
      coalesce(d.alternatives, '{}'), d.review_date, coalesce(d.status, 'active'), coalesce(d.created_at, now()),
      coalesce(d.updated_at, now()), d.priorities
    from jsonb_to_recordset(p_decisions) as d(id text, title text, category text, choice text, notes text,
      alternatives text[], review_date date, status text, created_at timestamptz, updated_at timestamptz, priorities jsonb)
  on conflict (id) do update set title = excluded.title, category = excluded.category, choice = excluded.choice,
    notes = excluded.notes, alternatives = excluded.alternatives, review_date = excluded.review_date,
    status = excluded.status, updated_at = now()
  where public.decisions.user_id = actor and not p_import_only;
  if (select count(*) from public.decisions where user_id = actor and id in
    (select item->>'id' from jsonb_array_elements(p_decisions) item)) <> jsonb_array_length(p_decisions) then
    raise exception 'A decision could not be saved to this account.' using errcode = '42501';
  end if;
  -- created_at and priorities are intentionally immutable on updates through this API.
end;
$$;
revoke all on function public.save_app_records(jsonb, jsonb, boolean, uuid) from public, anon;
grant execute on function public.save_app_records(jsonb, jsonb, boolean, uuid) to authenticated;

-- 202611190001_task_priority_defaults.sql
-- Preserve a starting copy without freezing a task that still follows universal priorities.
-- Existing task rows remain explicit overrides.
alter table public.task_priorities add column inherited boolean not null default false;

create function public.seed_claro_task_priorities() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.task_priorities(task_id, user_id, factor, weight, sort_order, name, description, color, inherited)
    select new.id, new.user_id, factor, weight, sort_order, name, description, color, true
    from public.universal_priorities where user_id = new.user_id;
  return new;
end;
$$;
revoke all on function public.seed_claro_task_priorities() from public, anon, authenticated;
create trigger claro_seed_task_priorities after insert on public.tasks
  for each row execute function public.seed_claro_task_priorities();

-- Backfill only tasks with no saved priorities; never overwrite custom balances.
insert into public.task_priorities(task_id, user_id, factor, weight, sort_order, name, description, color, inherited)
  select t.id, t.user_id, p.factor, p.weight, p.sort_order, p.name, p.description, p.color, true
  from public.tasks t join public.universal_priorities p on p.user_id = t.user_id
  where not exists (select 1 from public.task_priorities tp where tp.task_id = t.id);

-- Task teams may call this instead of a plain insert when collecting priorities before save.
-- The task and optional overrides commit together, before option generation starts.
create function public.create_task_with_priorities(p_task jsonb, p_expected_user_id uuid, p_factors jsonb default null)
returns text language plpgsql security invoker set search_path = '' as $$
declare actor uuid := auth.uid(); task_key text := p_task->>'id'; overrides jsonb;
begin
  if actor is null or actor is distinct from p_expected_user_id then
    raise exception 'Your account changed. Reopen the screen before saving.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_task) is distinct from 'object' or task_key is null or length(btrim(task_key)) = 0 then
    raise exception 'Expected a task with an ID.';
  end if;
  insert into public.tasks(id, user_id, title, notes, due_date, done)
    values (task_key, actor, p_task->>'title', coalesce(p_task->>'notes', ''), nullif(p_task->>'due_date', '')::date, false);
  if p_factors is not null then
    if jsonb_typeof(p_factors) <> 'array' or jsonb_array_length(p_factors) = 0 then
      raise exception 'Custom priorities must contain factors.';
    end if;
    -- Omitted universal factors are explicit exclusions, matching the existing editor.
    select p_factors || coalesce(jsonb_agg(jsonb_build_object(
      'factor', p.factor, 'weight', 0, 'name', p.name, 'description', p.description, 'color', p.color, 'excluded', true
    )), '[]'::jsonb) into overrides from public.universal_priorities p
    where p.user_id = actor and not exists (select 1 from jsonb_array_elements(p_factors) f where f->>'factor' = p.factor);
    perform public.save_priorities(overrides, task_key, actor);
  end if;
  return task_key;
end;
$$;
revoke all on function public.create_task_with_priorities(jsonb, uuid, jsonb) from public, anon;
grant execute on function public.create_task_with_priorities(jsonb, uuid, jsonb) to authenticated;

-- 202611190002_post_decision_tasks.sql
-- Follow-ups are distinct from public.tasks, which represent decisions to make.
alter table public.decisions add constraint claro_decisions_id_user_unique unique (id, user_id);
create table public.post_decision_tasks (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null references auth.users(id) on delete cascade,
  decision_id text not null,
  title text not null check (length(btrim(title)) between 1 and 120),
  notes text not null default '' check (length(notes) <= 2000),
  due_date date not null,
  done boolean not null default false,
  created_at timestamptz not null default now(),
  foreign key (decision_id, user_id) references public.decisions(id, user_id) on delete cascade
);
create index claro_post_decision_tasks_date on public.post_decision_tasks(user_id, due_date, id);
alter table public.post_decision_tasks enable row level security;
create policy claro_followups_owner on public.post_decision_tasks for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy claro_followups_guard on public.post_decision_tasks as restrictive for all to public
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke all on public.post_decision_tasks from anon;
grant select, insert, update, delete on public.post_decision_tasks to authenticated;

commit;
